mapper.select:
SELECT rr.RECOGNITION_ID as recognitionId, rr.CONTRACT_ID as contractId, rc.CONTRACT_NO as contractNo, rc.CONTRACT_NAME as contractName, rr.RECOGNITION_PERIOD as recognitionPeriod, rr.RECOGNITION_DATE as recognitionDate, rr.RECOGNITION_AMOUNT as recognitionAmount, rr.CUMULATIVE_AMOUNT as cumulativeAmount, rr.RECOGNITION_RATE as recognitionRate, rr.PERFORMANCE_PROGRESS as performanceProgress, rr.RECOGNITION_TYPE as recognitionType, CASE rr.RECOGNITION_TYPE WHEN 1 THEN '自动确认' WHEN 2 THEN '手动确认' ELSE '未知' END as recognitionTypeName, rr.RECOGNITION_BASIS as recognitionBasis, rr.VOUCHER_ID as voucherId, rr.CREATE_TIME as createTime, rr.UPDATE_TIME as updateTime FROM T_REVENUE_RECOGNITION rr LEFT JOIN T_REVENUE_CONTRACT rc ON rr.CONTRACT_ID = rc.CONTRACT_ID
rr.IS_DELETED = 0
AND rc.CONTRACT_NO LIKE '%' || #{param.contractNo} || '%'
AND rc.CONTRACT_NAME LIKE '%' || #{param.contractName} || '%'
AND rr.RECOGNITION_PERIOD = #{param.recognitionPeriod}
AND rr.RECOGNITION_TYPE = #{param.recognitionType}
AND rr.RECOGNITION_DATE BETWEEN #{param.startDate} AND #{param.endDate}
ORDER BY rr.RECOGNITION_DATE DESC, rr.CREATE_TIME DESC
